-- Weekly Schedule — 20 Jul to 9 Aug 2026, generated by AviCore's planner
-- from the published duty roster ("NEW Pilot Schedule 2026 (Include RR9)",
-- sheet "RR 2026") with every rule agreed in docs/WEEKLY-SCHEDULE-RULES.md:
--
--   * only pilots the roster shows on duty (O / N / ND)
--   * 12h minimum rest between duty end and next report
--     (night ends 05:30 -> earliest next report 17:30)
--   * rolling duty limits respected, and planned to the WARNING figure,
--     not the legal maximum - a seat that could only be filled by pushing
--     someone into the yellow was left unmanned instead
--   * no more than 6 night duties per 28-day cycle
--   * rotation Night -> OFF -> Crew 1 -> Crew 3 -> Crew 2 -> Crew 4
--   * pairing: never two Co-pilots; second seat prefers a Co-pilot
--   * work handed to whoever is carrying the least duty, and whoever has
--     flown least this cycle
--
-- RESULT: 165 assignments, zero red, zero yellow, zero conflicts.
-- Highest 7-day duty 53.5h (warning 54h, limit 60h); nights spread across
-- 18 pilots, nobody above 5.
--
-- Run AFTER sql/weekly-plan-setup.sql.
--
-- WHAT THIS RUN COULD NOT SEE: it was generated outside the app, so it has
-- no access to Night Currency, overdue training, recorded flight hours or
-- the 168h Recovery Rest cycle. It assumes every pilot is night current and
-- fully in date. Once loaded, press "Plan 30 Days" in the app to regenerate
-- against the real records - that result supersedes this one.

begin;

update public.pilot_weekly_plan
   set deleted_at = now()::text, modified_at = now()::text
 where date between '2026-07-20' and '2026-08-09'
   and deleted_at is null;


on conflict (uuid) do update set
  pilot_code  = excluded.pilot_code,
  level       = excluded.level,
  modified_at = excluded.modified_at,
  deleted_at  = null;

commit;

